-- remapath: what each REMA weapon still needs, for every family (Relic, Mythic, Empyrean, Ergon, Aeonic).
-- Pure Lua, no Windower calls, so tools/test-charsync-remapath.lua runs it offline.
-- Data: rema_paths.lua (GENERATED by ffxi-atlas src/market/rema_paths.py): per line a family, ordered steps and
-- the family's shared Oboro `tail`. A requirement is {kind item|currency|key_item|progress|flag, ref, qty, group}:
-- same group = alternatives (any one), different groups = all. have(kind, ref, qty) answers true / false /
-- nil, and nil means NO data source, which is shown as unknown and never as "not done".
local core = {}
local trials_ok, trial_paths = pcall(require, 'magian_paths')
if not trials_ok then trial_paths = {} end

-- Level x 10 plus the roman suffix, the same order rema_lua.py writes into rema_weapons.lua.
function core.stage_order(label)
    local lvl, suffix = tostring(label or ''):match('^%D*(%d+)%s*(I*)')
    if not lvl then return nil end
    return tonumber(lvl) * 10 + (({II = 1, III = 2})[suffix] or 0)
end

-- Highest held order per line from remacore.scan rows; aeonic weapons have order 0 and count as held.
function core.held(rows)
    local by = {}
    for _, r in ipairs(rows or {}) do
        local cur = by[r.line]
        if not cur or r.order > cur.order then by[r.line] = {order = r.order, kind = r.kind} end
    end
    return by
end

local function group_status(options, have)
    local unknown = false
    for _, n in ipairs(options) do
        local ok = have(n.kind, n.ref, n.qty)
        if ok then return true end
        if ok == nil then unknown = true end
    end
    if unknown then return nil end
    return false
end

-- 'ready' = every group satisfied, 'blocked' = some group has no way to be met, 'unknown' = no data for some.
function core.needs_status(needs, have)
    local groups, order = {}, {}
    for _, n in ipairs(needs or {}) do
        local g = n.group or 0
        if not groups[g] then groups[g] = {} order[#order + 1] = g end
        table.insert(groups[g], n)
    end
    local unknown = false
    for _, g in ipairs(order) do
        local s = group_status(groups[g], have)
        if s == false then return 'blocked' end
        if s == nil then unknown = true end
    end
    if #order == 0 then return 'unknown' end
    return unknown and 'unknown' or 'ready'
end

local function all_steps(paths, line, name)
    local steps = {}
    for _, s in ipairs(line.steps or {}) do
        if s.gap and trial_paths[name] then
            for _, trial in ipairs(trial_paths[name]) do steps[#steps + 1] = trial end
        else steps[#steps + 1] = s end
    end
    for _, s in ipairs((paths.tails or {})[line.tail] or {}) do steps[#steps + 1] = s end
    return steps
end
core.all_steps = all_steps

-- held: core.held(rows). Returns {line, family, held_order, steps = {{label, status, source, gap, uncached}}, next}.
function core.evaluate(paths, name, held, have)
    local line = paths.lines[name]
    if not line then return nil end
    local h = held[name]
    local out = {line = name, family = line.family, jobs = line.jobs, held = h ~= nil,
        held_order = h and h.order or nil, steps = {}}
    for _, s in ipairs(all_steps(paths, line, name)) do
        local status
        local o = core.stage_order(s.to_stage)
        local optional = s.optional or (s.from_stage and s.from_stage:find('Afterglow', 1, true)) ~= nil
        local afterglow = h and (h.order == 991 or h.order == 1191)
        if not s.trial and s.from_stage then
            if s.from_stage:find('Afterglow', 1, true) then optional = not afterglow
            elseif afterglow and (s.from_stage == '99' or s.from_stage == '119') then optional = true end
        end
        if s.trial then
            local proof = core.stage_order(s.proof_stage or s.to_stage)
            local proven = h and proof and not s.no_stage_proof and h.order >= proof
            if optional then proven = h and (h.order == 991 or h.order == 1191) end
            if proven then status = 'done' else status = core.needs_status(s.needs, have) end
        elseif optional and s.from_stage then
            -- A shared final stage does not establish which optional route was used.
            status = h and h.order == o and o == 1191 and 'done' or core.needs_status(s.needs, have)
        elseif h and (line.family == 'aeonic' or s.to_stage == nil or o == nil or h.order >= o) then status = 'done'
        elseif s.gap then status = 'gap'
        else status = core.needs_status(s.needs, have) end
        out.steps[#out.steps + 1] = {label = s.label, status = status, where = s.where, wait = s.wait,
            source = s.source, gap = s.gap, uncached = s.cached == false, needs = s.needs,
            trial = s.trial, optional = optional, stage_conflict = s.stage_conflict}
        if not out.next and status ~= 'done' and not optional then out.next = out.steps[#out.steps] end
    end
    return out
end

-- Holdings from the saved snapshot.tsv: item name -> count, key item names.
function core.parse_snapshot(text)
    local items, kis = {}, {}
    for l in (text or ''):gmatch('[^\r\n]+') do
        local f = {}
        for v in (l .. '\t'):gmatch('([^\t]*)\t') do f[#f + 1] = v end
        if f[1] == 'i' and f[6] then items[f[6]] = (items[f[6]] or 0) + (tonumber(f[5]) or 1)
        elseif f[1] == 'k' and f[3] then kis[f[3]] = true end
    end
    return {items = items, key_items = kis}
end

local function norm(s) return (tostring(s):lower():gsub('[^%w]', '')) end

-- sources: {snapshot = parse_snapshot(), currencies = remacore.parse_currencies(), progress = fn(key) -> bool|nil}
function core.make_have(sources)
    return function(kind, ref, qty)
        if kind == 'item' then
            if not sources.snapshot then return nil end
            return (sources.snapshot.items[ref] or 0) >= (qty or 1)
        elseif kind == 'key_item' then
            if not sources.snapshot then return nil end
            return sources.snapshot.key_items[ref] == true
        elseif kind == 'currency' then
            if not sources.currencies then return nil end
            local want, found = norm(ref), false
            for _, p in pairs(sources.currencies) do
                for _, f in ipairs(p.fields) do
                    if norm(f.field) == want then found = true if f.value >= (qty or 1) then return true end end
                end
            end
            if found then return false end
            return nil
        elseif kind == 'progress' then
            if not sources.progress then return nil end
            return sources.progress(ref)
        end
        return nil
    end
end

local MARK = {done = '[x]', ready = '[ready]', blocked = '[ ]', unknown = '[?]', gap = '[gap]'}
function core.lines(e)
    if not e then return {'No such REMA line.'} end
    local out = {('%s (%s%s)%s'):format(e.line, e.family, (e.jobs and #e.jobs > 0) and (', ' .. table.concat(e.jobs, '/')) or '',
        e.held and ', held' or ', not held')}
    for _, s in ipairs(e.steps) do
        out[#out + 1] = ('  %s %s%s%s%s'):format(MARK[s.status] or '[?]', s.label,
            s.where and (' @ ' .. s.where) or '', s.uncached and ' (not in cache)' or '',
            (s.optional and ' (optional)' or '') .. (s.stage_conflict and ' (source stage conflict; later-stage proof only)' or ''))
    end
    return out
end
return core
